using Backend.Exceptions;using Backend.Models;using Backend.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace Backend.Controllers;[ApiController][Route("api/[controller]")][Authorize]public class PuestoController : ControllerBase{    private readonly PuestoService _puestoService;    public PuestoController(PuestoService puestoService)    {        _puestoService = puestoService;    }    [HttpGet]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> ObtenerTodos([FromQuery] int skip = 0, [FromQuery] int take = 100)    {        var puestos = await _puestoService.GetPuestosAsync(skip, take);        return Ok(puestos);    }    [HttpGet("{id}")]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> ObtenerPorId(long id)    {        var puesto = await _puestoService.GetPuestoByIdAsync(id);        if (puesto is null)            return NotFound(new { mensaje = $"No se encontró el puesto con Id {id}." });        return Ok(puesto);    }    [HttpPost]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> Crear([FromBody] CrearPuestoModel model)    {        try        {            var puesto = await _puestoService.CreatePuestoAsync(model);            return CreatedAtAction(                nameof(ObtenerPorId),                new { id = puesto.Id },                puesto);        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpPut("{id}")]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> Actualizar(long id, [FromBody] ActualizarPuestoModel model)    {        try        {            var actualizado = await _puestoService.UpdatePuestoAsync(id, model);            if (!actualizado)                return NotFound(new { mensaje = $"No se encontró el puesto con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpDelete("{id}")]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> Eliminar(long id)    {        try        {            var eliminado = await _puestoService.DeletePuestoAsync(id);            if (!eliminado)                return NotFound(new { mensaje = $"No se encontró el puesto con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }}